sp_widget.client_script:
api.controller = function() {

    var c = this;


    /* =========================================
       FILTER VALUES
       ========================================= */

    c.searchText = "";

    c.statusFilter = "all";

    c.priorityFilter = "all";

    c.groupFilter = "all";


    /* =========================================
       FILTER RECORDS
       ========================================= */

    c.filteredRecords = function() {

        var records =
            c.data.records || [];

        var result = [];


        var search =
            (
                c.searchText ||
                ""
            ).toLowerCase();


        for (
            var i = 0;
            i < records.length;
            i++
        ) {

            var record =
                records[i];


            /* -------------------------------------
               SEARCH
               ------------------------------------- */

            var number =
                (
                    record.number ||
                    ""
                ).toLowerCase();


            var caller =
                (
                    record.caller ||
                    ""
                ).toLowerCase();


            var description =
                (
                    record.short_description ||
                    ""
                ).toLowerCase();


            var meal =
                (
                    record.meal_type ||
                    ""
                ).toLowerCase();


            var mess =
                (
                    record.mess_hall ||
                    ""
                ).toLowerCase();


            if (search) {

                var matches =
                    number.indexOf(search) !== -1 ||
                    caller.indexOf(search) !== -1 ||
                    description.indexOf(search) !== -1 ||
                    meal.indexOf(search) !== -1 ||
                    mess.indexOf(search) !== -1;


                if (!matches) {

                    continue;

                }

            }


            /* -------------------------------------
               STATUS
               ------------------------------------- */

            if (
                c.statusFilter !== "all" &&
                record.stateValue !=
                c.statusFilter
            ) {

                continue;

            }


            /* -------------------------------------
               PRIORITY
               ------------------------------------- */

            if (
                c.priorityFilter !== "all" &&
                record.priorityValue !=
                c.priorityFilter
            ) {

                continue;

            }


            /* -------------------------------------
               GROUP
               ------------------------------------- */

            if (
                c.groupFilter !== "all" &&
                record.assignment_group_id !=
                c.groupFilter
            ) {

                continue;

            }


            result.push(record);

        }


        return result;

    };


    /* =========================================
       CLEAR FILTERS
       ========================================= */

    c.clearFilters = function() {

        c.searchText = "";

        c.statusFilter = "all";

        c.priorityFilter = "all";

        c.groupFilter = "all";

    };


    /* =========================================
       REFRESH
       ========================================= */

    c.refresh = function() {

        c.server.get({}).then(
            function(response) {

                c.data =
                    response.data;

            }
        );

    };


    /* =========================================
       GO BACK
       ========================================= */

    c.goBack = function() {

        /*
         * Send Manager to Manager Home.
         * Send Admin to Admin Home.
         */

        if (
            c.data.isAdmin
        ) {

            window.location.href =
                "?id=cfms_admin";

        } else {

            window.location.href =
                "?id=cfms_manager";

        }

    };

};

sp_widget.css:
/* =========================================
   CFMS RECORDS
   ========================================= */

.cfms-records {

  min-height: 100vh;

  background: #f0fbfc;

  padding: 30px;

  font-family:
    'Segoe UI',
    Tahoma,
    Geneva,
    Verdana,
    sans-serif;

  color: #263238;
}


/* =========================================
   HEADER
   ========================================= */

.records-header {

  background:
    linear-gradient(
      135deg,
      #00acc1,
      #4dd0e1
    );

  color: white;

  border-radius: 20px;

  padding: 27px 32px;

  display: flex;

  align-items: center;

  justify-content: space-between;

  margin-bottom: 25px;

  box-shadow:
    0 8px 25px
    rgba(0,172,193,0.18);
}


.header-left {

  display: flex;

  align-items: center;

  gap: 17px;
}


.records-icon {

  width: 58px;

  height: 58px;

  border-radius: 15px;

  background:
    rgba(255,255,255,0.18);

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 27px;
}


.records-header h1 {

  margin: 0 0 6px;

  font-size: 29px;

  font-weight: 700;
}


.records-header p {

  margin: 0;

  font-size: 14px;

  opacity: 0.95;
}


/* Header buttons */

.header-actions {

  display: flex;

  gap: 10px;
}


.header-btn,
.refresh-btn {

  border: none;

  padding: 11px 17px;

  border-radius: 10px;

  font-weight: 600;

  cursor: pointer;

  transition: 0.2s;
}


.header-btn {

  background: white;

  color: #008c9e;
}


.refresh-btn {

  background:
    rgba(255,255,255,0.18);

  color: white;

  border:
    1px solid
    rgba(255,255,255,0.4);
}


.header-btn:hover,
.refresh-btn:hover {

  transform: translateY(-2px);
}


/* =========================================
   ALERT
   ========================================= */

.alert {

  padding: 14px 18px;

  border-radius: 10px;

  margin-bottom: 20px;

  font-weight: 600;
}


.error-alert {

  background: #ffebee;

  color: #c62828;

  border: 1px solid #ef9a9a;
}


/* =========================================
   SUMMARY
   ========================================= */

.summary-grid {

  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 18px;

  margin-bottom: 22px;
}


.summary-card {

  background: white;

  border-radius: 15px;

  padding: 21px;

  display: flex;

  align-items: center;

  gap: 15px;

  border:
    1px solid
    #e3f2f4;

  box-shadow:
    0 4px 15px
    rgba(38,50,56,0.06);
}


.summary-icon {

  width: 50px;

  height: 50px;

  border-radius: 12px;

  background: #e0f7fa;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 22px;
}


.summary-card span {

  display: block;

  color: #78909c;

  font-size: 12px;

  margin-bottom: 5px;
}


.summary-card strong {

  display: block;

  font-size: 26px;
}


/* =========================================
   FILTER
   ========================================= */

.filter-card {

  background: white;

  border-radius: 16px;

  padding: 22px;

  margin-bottom: 22px;

  box-shadow:
    0 4px 15px
    rgba(38,50,56,0.06);
}


.filter-title {

  display: flex;

  justify-content: space-between;

  align-items: center;

  margin-bottom: 17px;
}


.filter-title h2 {

  margin: 0;

  font-size: 18px;
}


.filter-title span {

  background: #e0f7fa;

  color: #008c9e;

  padding: 6px 12px;

  border-radius: 20px;

  font-size: 11px;

  font-weight: 700;
}


.filter-row {

  display: grid;

  grid-template-columns:
    1fr
    180px
    180px
    200px
    auto;

  gap: 11px;
}


.search-box {

  display: flex;

  align-items: center;

  gap: 9px;

  background: #f7fcfd;

  border:
    1px solid
    #dceff1;

  border-radius: 10px;

  padding: 0 13px;
}


.search-box input {

  width: 100%;

  border: none;

  outline: none;

  background: transparent;

  padding: 11px 0;

  font-size: 13px;
}


.filter-row select {

  border:
    1px solid
    #dceff1;

  background: #f7fcfd;

  border-radius: 10px;

  padding: 11px 12px;

  color: #455a64;

  outline: none;

  font-size: 13px;
}


.clear-btn {

  border: none;

  background: #eceff1;

  color: #455a64;

  border-radius: 10px;

  padding: 0 17px;

  font-weight: 600;

  cursor: pointer;
}


.clear-btn:hover {

  background: #cfd8dc;
}


/* =========================================
   RECORDS CARD
   ========================================= */

.records-card {

  background: white;

  border-radius: 17px;

  padding: 25px;

  box-shadow:
    0 5px 20px
    rgba(38,50,56,0.06);
}


.records-title {

  display: flex;

  justify-content: space-between;

  align-items: center;

  padding-bottom: 19px;

  border-bottom:
    1px solid
    #edf5f6;

  margin-bottom: 10px;
}


.records-title h2 {

  margin: 0 0 5px;

  font-size: 20px;
}


.records-title p {

  margin: 0;

  color: #78909c;

  font-size: 12px;
}


.record-count {

  background: #e0f7fa;

  color: #008c9e;

  padding: 7px 13px;

  border-radius: 20px;

  font-size: 11px;

  font-weight: 700;
}


/* =========================================
   TABLE
   ========================================= */

.table-wrapper {

  width: 100%;

  overflow-x: auto;
}


.records-table {

  width: 100%;

  border-collapse: collapse;

  min-width: 1100px;
}


.records-table thead th {

  background: #f7fcfd;

  color: #607d8b;

  font-size: 11px;

  font-weight: 700;

  text-align: left;

  padding: 13px 12px;

  border-bottom:
    1px solid
    #e4eff1;

  white-space: nowrap;
}


.records-table tbody td {

  padding: 15px 12px;

  border-bottom:
    1px solid
    #edf5f6;

  vertical-align: middle;

  font-size: 12px;
}


.records-table tbody tr:hover {

  background: #f9fdfe;
}


/* =========================================
   TICKET
   ========================================= */

.ticket-number {

  color: #008c9e;

  font-weight: 700;

  white-space: nowrap;
}


/* =========================================
   STUDENT
   ========================================= */

.student-cell {

  display: flex;

  align-items: center;

  gap: 9px;

  min-width: 140px;
}


.student-avatar {

  width: 32px;

  height: 32px;

  border-radius: 9px;

  background: #e0f7fa;

  color: #008c9e;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 12px;

  font-weight: 700;
}


.student-cell strong {

  display: block;

  font-size: 12px;

  max-width: 120px;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}


.student-cell span {

  display: block;

  color: #90a4ae;

  font-size: 10px;

  margin-top: 3px;

  max-width: 120px;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}


/* =========================================
   REQUEST
   ========================================= */

.request-cell {

  max-width: 230px;
}


.request-cell strong {

  display: block;

  font-size: 12px;

  margin-bottom: 4px;
}


.request-cell span {

  display: block;

  color: #90a4ae;

  font-size: 10px;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;
}


/* =========================================
   NORMAL TEXT
   ========================================= */

.normal-text {

  color: #546e7a;

  white-space: nowrap;
}


.group-text {

  color: #546e7a;

  font-size: 11px;

  white-space: nowrap;
}


.date-text {

  color: #78909c;

  font-size: 10px;

  white-space: nowrap;
}


/* =========================================
   BADGES
   ========================================= */

.priority-badge,
.status-badge {

  display: inline-block;

  padding: 6px 9px;

  border-radius: 20px;

  font-size: 10px;

  font-weight: 700;

  white-space: nowrap;
}


/* Priority */

.priority-critical {

  background: #ffebee;

  color: #c62828;
}


.priority-high {

  background: #fff3e0;

  color: #ef6c00;
}


.priority-medium {

  background: #fffde7;

  color: #827717;
}


.priority-low {

  background: #e8f5e9;

  color: #2e7d32;
}


/* Status */

.status-open {

  background: #fff3e0;

  color: #ef6c00;
}


.status-progress {

  background: #e3f2fd;

  color: #1565c0;
}


.status-resolved {

  background: #e8f5e9;

  color: #2e7d32;
}


/* =========================================
   EMPTY
   ========================================= */

.empty-state {

  text-align: center;

  padding: 70px 20px;
}


.empty-icon {

  font-size: 50px;

  margin-bottom: 13px;
}


.empty-state h3 {

  margin: 0 0 7px;

  font-size: 19px;
}


.empty-state p {

  margin: 0;

  color: #90a4ae;

  font-size: 13px;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 1100px) {

  .summary-grid {

    grid-template-columns:
      repeat(2, 1fr);
  }


  .filter-row {

    grid-template-columns:
      1fr 1fr;
  }


  .search-box {

    grid-column:
      span 2;
  }

}


@media (max-width: 700px) {

  .cfms-records {

    padding: 15px;
  }


  .records-header {

    flex-direction: column;

    align-items: flex-start;

    gap: 15px;
  }


  .header-actions {

    width: 100%;
  }


  .header-btn,
  .refresh-btn {

    flex: 1;
  }


  .summary-grid {

    grid-template-columns: 1fr;
  }


  .filter-row {

    grid-template-columns: 1fr;
  }


  .search-box {

    grid-column: auto;
  }


  .records-title {

    align-items: flex-start;

    gap: 10px;

    flex-direction: column;
  }

}

sp_widget.script:
(function() {

    data.total = 0;
    data.active = 0;
    data.resolved = 0;
    data.critical = 0;

    data.records = [];
    data.groups = [];

    data.error = "";


    /* =========================================
       SECURITY
       ========================================= */

    if (!gs.isLoggedIn()) {

        data.redirect = "cfms_login";

        return;
    }


    /*
     * Allow Admin or Manager.
     */

    if (
        !gs.hasRole("admin") &&
        !gs.hasRole("cfms_manager")
    ) {

        data.error =
            "You are not authorized to access CFMS Records.";

        data.redirect =
            "cfms_home";

        return;
    }


    /* =========================================
       GET ASSIGNMENT GROUPS
       ========================================= */

    var groupGR =
        new GlideRecord("sys_user_group");

    groupGR.addActiveQuery();

    groupGR.orderBy("name");

    groupGR.query();


    while (groupGR.next()) {

        data.groups.push({

            id:
                groupGR.getUniqueValue(),

            name:
                groupGR.getValue("name")

        });

    }


    /* =========================================
       INCIDENT RECORDS
       ========================================= */

    var gr =
        new GlideRecord("incident");

    gr.orderByDesc("sys_created_on");

    gr.query();


    while (gr.next()) {

        data.total++;


        var state =
            gr.getValue("state");


        /* -----------------------------------------
           ACTIVE
           ----------------------------------------- */

        if (
            state != "6" &&
            state != "7"
        ) {

            data.active++;

        } else {

            data.resolved++;

        }


        /* -----------------------------------------
           PRIORITY
           ----------------------------------------- */

        var priority =
            gr.getValue("priority");


        var priorityText =
            gr.getDisplayValue("priority");


        var priorityClass =
            "priority-medium";


        if (priority == "1") {

            data.critical++;

            priorityText =
                "Critical";

            priorityClass =
                "priority-critical";

        } else if (priority == "2") {

            priorityText =
                "High";

            priorityClass =
                "priority-high";

        } else if (priority == "3") {

            priorityText =
                "Medium";

            priorityClass =
                "priority-medium";

        } else if (priority == "4") {

            priorityText =
                "Low";

            priorityClass =
                "priority-low";

        }


        /* -----------------------------------------
           STATUS
           ----------------------------------------- */

        var stateText =
            gr.getDisplayValue("state");


        var statusClass =
            "status-open";


        if (state == "2") {

            statusClass =
                "status-progress";

        } else if (
            state == "6" ||
            state == "7"
        ) {

            statusClass =
                "status-resolved";

        }


        /* -----------------------------------------
           CALLER
           ----------------------------------------- */

        var caller =
            gr.getDisplayValue("caller_id");


        var initial = "U";


        if (caller) {

            initial =
                caller
                .substring(0, 1)
                .toUpperCase();

        }


        /* -----------------------------------------
           CUSTOM CFMS FIELDS
           ----------------------------------------- */

        var mealType = "";
        var messHall = "";
        var useCase = "";


        if (
            gr.isValidField(
                "u_cfms_meal_type"
            )
        ) {

            mealType =
                gr.getDisplayValue(
                    "u_cfms_meal_type"
                );

        }


        if (
            gr.isValidField(
                "u_cfms_mess_hall"
            )
        ) {

            messHall =
                gr.getDisplayValue(
                    "u_cfms_mess_hall"
                );

        }


        if (
            gr.isValidField(
                "u_cfms_use_case"
            )
        ) {

            useCase =
                gr.getDisplayValue(
                    "u_cfms_use_case"
                );

        }


        /* -----------------------------------------
           RECORD
           ----------------------------------------- */

        data.records.push({

            sys_id:
                gr.getUniqueValue(),

            number:
                gr.getValue("number"),

            caller:
                caller,

            initial:
                initial,

            short_description:
                gr.getValue(
                    "short_description"
                ),

            description:
                gr.getValue(
                    "description"
                ) || "",

            use_case:
                useCase,

            meal_type:
                mealType,

            mess_hall:
                messHall,

            assignment_group:
                gr.getDisplayValue(
                    "assignment_group"
                ),

            assignment_group_id:
                gr.getValue(
                    "assignment_group"
                ),

            assigned_to:
                gr.getDisplayValue(
                    "assigned_to"
                ),

            state:
                stateText,

            stateValue:
                state,

            statusClass:
                statusClass,

            priority:
                priorityText,

            priorityValue:
                priority,

            priorityClass:
                priorityClass,

            created:
                gr.getDisplayValue(
                    "sys_created_on"
                )

        });

    }

})();
